package com.ruoyi.framework.audit;
import java.util.*;import java.time.*;import java.nio.file.*;import com.alibaba.fastjson2.*;import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;
@Component @EnableScheduling public class AuditDelivery {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;public AuditDelivery(JdbcTemplate jdbc,PlatformTransactionManager m){this.jdbc=jdbc;tx=new TransactionTemplate(m);}
 private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger(AuditDelivery.class);
 @Scheduled(fixedDelay=250) public void deliver(){long deadline=System.nanoTime()+2_000_000_000L;int count=0;try{while(count<1000&&System.nanoTime()<deadline){List<String> selected=new ArrayList<>();try{int done=tx.execute(t->{var rows=jdbc.queryForList("SELECT event_id,event_json FROM audit_outbox WHERE status='PENDING' AND next_retry<=NOW() ORDER BY next_retry,create_time,event_id LIMIT 100 FOR UPDATE SKIP LOCKED");rows.forEach(r->selected.add(r.get("event_id").toString()));if(rows.isEmpty())return 0;storeBatch(rows.stream().map(r->JSON.parseObject(r.get("event_json").toString())).toList());jdbc.batchUpdate("UPDATE audit_outbox SET status='DELIVERED',delivered_time=NOW() WHERE event_id=?",selected.stream().map(id->new Object[]{id}).toList());return rows.size();});if(done==0)break;count+=done;}catch(Exception failure){if(selected.isEmpty())throw failure;for(String id:selected){deliverOne(id);count++;if(count>=1000)break;}}}replayFallback();}catch(Exception unavailable){LOG.warn("AUDIT_DELIVERY_UNAVAILABLE {}",unavailable.getClass().getSimpleName());}}
 private void deliverOne(String id){try{tx.executeWithoutResult(t->{var rows=jdbc.queryForList("SELECT event_json,status FROM audit_outbox WHERE event_id=? FOR UPDATE",id);if(rows.isEmpty()||!"PENDING".equals(rows.get(0).get("status")))return;store(JSON.parseObject(rows.get(0).get("event_json").toString()));jdbc.update("UPDATE audit_outbox SET status='DELIVERED',delivered_time=NOW() WHERE event_id=?",id);});}catch(Exception failure){jdbc.update("UPDATE audit_outbox SET next_retry=DATE_ADD(NOW(),INTERVAL CASE attempts WHEN 0 THEN 1 WHEN 1 THEN 5 WHEN 2 THEN 30 WHEN 3 THEN 120 ELSE 600 END SECOND),attempts=attempts+1 WHERE event_id=? AND status='PENDING'",id);LOG.warn("AUDIT_EVENT_RETRY {} {}",id,failure.getClass().getSimpleName());}}
 private void storeBatch(List<JSONObject> events){
  List<Object[]> login=new ArrayList<>(),operations=new ArrayList<>();List<JSONObject> ops=new ArrayList<>();Set<Long> missingFactories=new TreeSet<>();
  for(var e:events)if(!"login".equals(e.getString("kind"))&&e.get("factory")!=null&&e.getString("factoryName")==null)missingFactories.add(e.getLong("factory"));
  Map<Long,String> names=new HashMap<>();if(!missingFactories.isEmpty()){String placeholders=String.join(",",Collections.nCopies(missingFactories.size(),"?"));jdbc.queryForList("SELECT factory_id,factory_name FROM metal_factory WHERE factory_id IN ("+placeholders+")",missingFactories.toArray()).forEach(r->names.put(((Number)r.get("factory_id")).longValue(),r.get("factory_name").toString()));}
  for(var e:events){if("login".equals(e.getString("kind"))){login.add(new Object[]{e.get("event"),e.get("trace"),e.get("actor"),e.get("ip"),e.get("browser"),e.get("status"),e.get("message"),e.get("reason"),LocalDateTime.parse(e.getString("time"))});continue;}
   String changes=AuditRedactor.json(e.get("changes"),16000);boolean truncated=changes.length()>=16000||Objects.toString(e.get("request"),"").length()>=4096||Objects.toString(e.get("response"),"").length()>=4096;if(changes.length()>=16000)changes=JSON.toJSONString(Map.of("truncated",true,"summary","变更超过16KB"));
   operations.add(new Object[]{e.get("event"),e.get("trace"),e.get("actorId"),e.get("actorFactory"),e.get("factory"),e.getString("factoryName")==null?names.get(e.getLong("factory")):e.getString("factoryName"),e.get("actorName"),shorten(e.getString("title"),50),0,e.get("actor"),e.get("path"),e.get("verb"),"SUCCESS".equals(e.get("code"))?0:1,e.get("code"),e.get("request"),e.get("response"),shorten(e.getString("error"),2000),LocalDateTime.parse(e.getString("time")),e.get("cost"),e.get("path"),e.get("action"),e.get("path"),e.get("businessCode"),e.get("objectType"),JSON.toJSONString(e.get("objects")),changes,e.get("replayed"),truncated});ops.add(e);
  }
  if(!login.isEmpty())jdbc.batchUpdate("INSERT IGNORE INTO sys_logininfor(event_id,trace_id,user_name,ipaddr,browser,status,msg,reason_category,login_time) VALUES(?,?,?,?,?,?,?,?,?)",login);
  if(!operations.isEmpty()){
   jdbc.batchUpdate("INSERT IGNORE INTO sys_oper_log(event_id,trace_id,actor_user_id,actor_factory_id,business_factory_id,factory_name,actor_name,title,business_type,oper_name,oper_url,request_method,status,result_code,oper_param,json_result,error_msg,oper_time,cost_time,module_code,action_code,event_key,business_code,object_type,objects_json,changes_json,replayed,truncated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",operations);
   String placeholders=String.join(",",Collections.nCopies(ops.size(),"?"));Map<String,Long> ids=new HashMap<>();jdbc.queryForList("SELECT event_id,oper_id FROM sys_oper_log WHERE event_id IN ("+placeholders+")",ops.stream().map(e->e.get("event")).toArray()).forEach(r->ids.put(r.get("event_id").toString(),((Number)r.get("oper_id")).longValue()));
   List<Object[]> scopes=new ArrayList<>();for(var e:ops){var factories=e.getJSONArray("factories");if(factories!=null)for(Object factory:factories)scopes.add(new Object[]{ids.get(e.getString("event")),factory});}if(!scopes.isEmpty())jdbc.batchUpdate("INSERT IGNORE INTO audit_scope(oper_id,factory_id) VALUES(?,?)",scopes);
  }
 }
 private void store(JSONObject e){if("login".equals(e.getString("kind"))){jdbc.update("INSERT IGNORE INTO sys_logininfor(event_id,trace_id,user_name,ipaddr,browser,status,msg,reason_category,login_time) VALUES(?,?,?,?,?,?,?,?,?)",e.get("event"),e.get("trace"),e.get("actor"),e.get("ip"),e.get("browser"),e.get("status"),e.get("message"),e.get("reason"),LocalDateTime.parse(e.getString("time")));return;}String factoryName=e.getString("factoryName");if(factoryName==null&&e.get("factory")!=null){var rows=jdbc.queryForList("SELECT factory_name FROM metal_factory WHERE factory_id=?",e.get("factory"));if(!rows.isEmpty())factoryName=rows.get(0).get("factory_name").toString();}String changes=AuditRedactor.json(e.get("changes"),16000);boolean truncated=changes.length()>=16000||e.getString("request").length()>=4096||e.getString("response").length()>=4096; if(changes.length()>=16000)changes=JSON.toJSONString(Map.of("truncated",true,"summary","变更超过16KB"));jdbc.update("INSERT IGNORE INTO sys_oper_log(event_id,trace_id,actor_user_id,actor_factory_id,business_factory_id,factory_name,actor_name,title,business_type,oper_name,oper_url,request_method,status,result_code,oper_param,json_result,error_msg,oper_time,cost_time,module_code,action_code,event_key,business_code,object_type,objects_json,changes_json,replayed,truncated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",e.get("event"),e.get("trace"),e.get("actorId"),e.get("actorFactory"),e.get("factory"),factoryName,e.get("actorName"),shorten(e.getString("title"),50),0,e.get("actor"),e.get("path"),e.get("verb"),"SUCCESS".equals(e.get("code"))?0:1,e.get("code"),e.get("request"),e.get("response"),shorten(e.getString("error"),2000),LocalDateTime.parse(e.getString("time")),e.get("cost"),e.get("path"),e.get("action"),e.get("path"),e.get("businessCode"),e.get("objectType"),JSON.toJSONString(e.get("objects")),changes,e.get("replayed"),truncated);Long id=jdbc.queryForObject("SELECT oper_id FROM sys_oper_log WHERE event_id=?",Long.class,e.get("event"));var factories=e.getJSONArray("factories");if(factories!=null)for(Object factory:factories)jdbc.update("INSERT IGNORE INTO audit_scope(oper_id,factory_id) VALUES(?,?)",id,factory);}
 private String shorten(String s,int n){return s==null?"":s.substring(0,Math.min(n,s.length()));}
 private void replayFallback(){Path file=Path.of("logs/audit-fallback.jsonl");if(!Files.exists(file))return;try{long offset=jdbc.queryForList("SELECT file_offset FROM audit_file_cursor WHERE file_name='audit-fallback.jsonl'").stream().mapToLong(r->((Number)r.get("file_offset")).longValue()).findFirst().orElse(0);try(var input=new java.io.RandomAccessFile(file.toFile(),"r")){input.seek(Math.min(offset,input.length()));for(int i=0;i<100;i++){String line=input.readLine();if(line==null)break;JSONObject event=JSON.parseObject(new String(line.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1),java.nio.charset.StandardCharsets.UTF_8));jdbc.update("INSERT IGNORE INTO audit_outbox(event_id,event_json) VALUES(?,?)",event.getString("event"),JSON.toJSONString(event));jdbc.update("INSERT INTO audit_file_cursor(file_name,file_offset) VALUES('audit-fallback.jsonl',?) ON DUPLICATE KEY UPDATE file_offset=VALUES(file_offset)",input.getFilePointer());}}}catch(Exception ignored){}}
}
